length = int(input())
height = int(input())
width = int(input())

d1 = (length**2+height**2)**0.5
d2 = (length**2+width**2)**0.5
d3 = (width**2+height**2)**0.5

if length!=0 and height!=0 and width!=0:
    if d1 == round(d1) and d2 == round(d2) and d3 == round(d3):
        print("Euler brick")
    else:
        print("Regular brick")
else:
    print("Not a brick")
